CREATE TABLE cabins (
    cabin_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cabin_number INTEGER NOT NULL UNIQUE
);

CREATE TABLE request_categories (
    category_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(120) NOT NULL,
    type VARCHAR(20) NOT NULL,
    description VARCHAR(255) NOT NULL,
    icon VARCHAR(80) NOT NULL,
    active BOOLEAN NOT NULL,
    CONSTRAINT ck_request_categories_type CHECK (type IN ('INCIDENT', 'SERVICE'))
);

CREATE TABLE request_subcategories (
    subcategory_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    category_id BIGINT NOT NULL,
    name VARCHAR(160) NOT NULL,
    description VARCHAR(255) NOT NULL,
    icon VARCHAR(80) NOT NULL,
    active BOOLEAN NOT NULL,
    CONSTRAINT fk_request_subcategories_category FOREIGN KEY (category_id)
        REFERENCES request_categories (category_id)
);

CREATE TABLE service_requests (
    service_request_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cabin_id BIGINT NOT NULL,
    category_id BIGINT NOT NULL,
    subcategory_id BIGINT NOT NULL,
    quantity INTEGER,
    preferred_delivery VARCHAR(40),
    status VARCHAR(20) NOT NULL,
    created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL,
    CONSTRAINT fk_service_requests_cabin FOREIGN KEY (cabin_id) REFERENCES cabins (cabin_id),
    CONSTRAINT fk_service_requests_category FOREIGN KEY (category_id) REFERENCES request_categories (category_id),
    CONSTRAINT fk_service_requests_subcategory FOREIGN KEY (subcategory_id) REFERENCES request_subcategories (subcategory_id),
    CONSTRAINT ck_service_requests_quantity CHECK (quantity IS NULL OR quantity >= 1),
    CONSTRAINT ck_service_requests_status CHECK (status IN ('PENDING', 'ASSIGNED', 'IN_PROGRESS', 'RESOLVED'))
);

CREATE TABLE request_status_history (
    history_request_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_request_id BIGINT NOT NULL,
    previous_status VARCHAR(20),
    new_status VARCHAR(20) NOT NULL,
    changed_at TIMESTAMP NOT NULL,
    CONSTRAINT fk_request_status_history_request FOREIGN KEY (service_request_id)
        REFERENCES service_requests (service_request_id)
);














